CREATE FUNCTION hive_tag_search(tags text[]) RETURNS tsvector LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$ SELECT to_tsvector('english', array_to_string(tags, ' ')) $$;
CREATE TABLE teams (id text PRIMARY KEY, name text NOT NULL, invite_code text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE members (id text PRIMARY KEY, team_id text NOT NULL REFERENCES teams(id), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz, UNIQUE (id, team_id));
CREATE TABLE api_keys (id text PRIMARY KEY, team_id text NOT NULL REFERENCES teams(id), member_id text NOT NULL, key_hash text NOT NULL UNIQUE, prefix text NOT NULL, label text NOT NULL DEFAULT 'Agent key', created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz, revoked_at timestamptz, FOREIGN KEY (member_id, team_id) REFERENCES members(id, team_id));
CREATE TABLE web_sessions (id text PRIMARY KEY, member_id text NOT NULL, team_id text NOT NULL REFERENCES teams(id), token_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, FOREIGN KEY (member_id, team_id) REFERENCES members(id, team_id));
CREATE TABLE learnings (id text PRIMARY KEY, team_id text NOT NULL REFERENCES teams(id), member_id text NOT NULL, title text NOT NULL, body text NOT NULL, kind text NOT NULL CHECK (kind IN ('learning','gotcha','decision','snippet','incident')), tags text[] NOT NULL DEFAULT '{}', repo text, paths text[] NOT NULL DEFAULT '{}', confidence real NOT NULL CHECK (confidence BETWEEN 0 AND 1), source text NOT NULL CHECK (source IN ('claude-code','codex','manual')), session_ref text, push_count integer NOT NULL DEFAULT 1, up_votes integer NOT NULL DEFAULT 0, down_votes integer NOT NULL DEFAULT 0, outdated_votes integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), last_pushed_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (member_id, team_id) REFERENCES members(id, team_id), UNIQUE (id, team_id), search tsvector GENERATED ALWAYS AS (setweight(to_tsvector('english', title), 'A') || setweight(hive_tag_search(tags), 'B') || setweight(to_tsvector('english', body), 'C')) STORED);
CREATE INDEX learnings_search_idx ON learnings USING gin(search);
CREATE INDEX learnings_team_created_idx ON learnings(team_id, created_at DESC);
CREATE INDEX learnings_team_repo_idx ON learnings(team_id, repo);
CREATE TABLE learning_pushes (id text PRIMARY KEY, learning_id text NOT NULL, team_id text NOT NULL REFERENCES teams(id), member_id text NOT NULL, source text NOT NULL, session_ref text, merged boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (learning_id, team_id) REFERENCES learnings(id, team_id), FOREIGN KEY (member_id, team_id) REFERENCES members(id, team_id));
CREATE TABLE feedback (learning_id text NOT NULL, member_id text NOT NULL, team_id text NOT NULL REFERENCES teams(id), vote text NOT NULL CHECK (vote IN ('up','down','outdated')), note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (learning_id, member_id), FOREIGN KEY (learning_id, team_id) REFERENCES learnings(id, team_id), FOREIGN KEY (member_id, team_id) REFERENCES members(id, team_id));
CREATE TABLE ask_log (id text PRIMARY KEY, team_id text NOT NULL REFERENCES teams(id), member_id text NOT NULL, question text NOT NULL, answer text NOT NULL, cited_ids text[] NOT NULL DEFAULT '{}', synthesized boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (member_id, team_id) REFERENCES members(id, team_id));
CREATE TABLE early_access (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL, company text NOT NULL, team_size text NOT NULL, source text, created_at timestamptz NOT NULL DEFAULT now());
